"use client"

import * as React from "react"
import { useChat } from "@ai-sdk/react"

import { createChat, getMessageText } from "@/lib/ai"
import { PartFile } from "@/registry/bases/radix/blocks/preview-03/components/part-file"
import { PartText } from "@/registry/bases/radix/blocks/preview-03/components/part-text"
import { PromptInput } from "@/registry/bases/radix/blocks/preview-03/components/prompt-input"
import { Example } from "@/registry/bases/radix/components/example"
import { Button } from "@/registry/bases/radix/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/registry/bases/radix/ui/card"
import {
  Marker,
  MarkerContent,
  MarkerIcon,
} from "@/registry/bases/radix/ui/marker"
import { Message, MessageContent } from "@/registry/bases/radix/ui/message"
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/registry/bases/radix/ui/message-scroller"
import { Spinner } from "@/registry/bases/radix/ui/spinner"
import { IconPlaceholder } from "@/app/(app)/create/components/icon-placeholder"

const chat = createChat()
  .user("Review these files and tell me what stands out.", {
    files: [
      {
        filename: "workspace.png",
        mediaType: "image/png",
        url: "https://images.unsplash.com/photo-1497366754035-f200968a6e72?w=900&auto=format&fit=crop&q=80",
      },
      {
        filename: "research-brief.pdf",
        mediaType: "application/pdf",
        url: "https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf",
      },
    ],
  })
  .sleep(1000)
  .assistant(({ writer }) => {
    writer.text(
      "The image reads like a focused workspace, while the document should be treated as the source of record. I would summarize the PDF first, then use the image only as supporting context."
    )
    writer.file({
      filename: "annotated-workspace.png",
      mediaType: "image/png",
      url: "https://images.unsplash.com/photo-1497366811353-6870744d04b2?w=900&auto=format&fit=crop&q=80",
    })
    writer.file({
      filename: "file-review-notes.pdf",
      mediaType: "application/pdf",
      url: "https://example.com/file-review-notes.pdf",
    })
  })

const initialMessages = chat.get(0)
const transport = chat.transport()

export function FilesChat() {
  const { status, messages, sendMessage, setMessages } = useChat({
    messages: initialMessages,
    transport,
  })
  const nextMessage = chat.next(messages)
  const isBusy = status === "submitted" || status === "streaming"

  const onSubmit = (input: string) => {
    if (!input.trim()) {
      return
    }

    if (nextMessage && input === getMessageText(nextMessage)) {
      void sendMessage(nextMessage)
      return
    }

    void sendMessage({ text: input })
  }

  return (
    <Example
      title="Files"
      className="bg-transparent p-0"
      containerClassName="flex-1"
    >
      <Card className="max-h-140 min-h-0 flex-1">
        <CardHeader>
          <CardTitle>File review</CardTitle>
          <CardDescription>Image and document file parts.</CardDescription>
          <CardAction>
            <Button
              variant="outline"
              size="icon"
              aria-label="Start over"
              onClick={() => setMessages(initialMessages)}
            >
              <IconPlaceholder
                lucide="PlusIcon"
                tabler="IconPlus"
                hugeicons="PlusSignIcon"
                phosphor="PlusIcon"
                remixicon="RiAddLine"
              />
            </Button>
          </CardAction>
        </CardHeader>
        <CardContent className="flex-1 overflow-hidden p-0">
          <MessageScrollerProvider>
            <MessageScroller>
              <MessageScrollerViewport>
                <MessageScrollerContent className="p-(--card-spacing)">
                  {messages.map((message) => (
                    <MessageScrollerItem
                      key={message.id}
                      messageId={message.id}
                      scrollAnchor={message.role === "user"}
                    >
                      <Message
                        align={message.role === "user" ? "end" : "start"}
                        data-role={message.role}
                      >
                        <MessageContent
                          className={
                            message.role === "user"
                              ? "flex-col items-end gap-2"
                              : "flex-col items-start gap-2"
                          }
                        >
                          {message.parts.map((part, index) =>
                            part.type === "file" ? (
                              <PartFile
                                key={`${message.id}-${index}`}
                                part={part}
                              />
                            ) : null
                          )}
                          {message.parts.map((part, index) =>
                            part.type === "text" ? (
                              <PartText
                                key={`${message.id}-${index}`}
                                part={part}
                                variant={
                                  message.role === "user" ? "bubble" : "default"
                                }
                              />
                            ) : null
                          )}
                        </MessageContent>
                      </Message>
                    </MessageScrollerItem>
                  ))}
                  {status === "submitted" ? (
                    <MessageScrollerItem scrollAnchor={false}>
                      <Marker role="status">
                        <MarkerIcon>
                          <Spinner />
                        </MarkerIcon>
                        <MarkerContent>Thinking...</MarkerContent>
                      </Marker>
                    </MessageScrollerItem>
                  ) : null}
                </MessageScrollerContent>
              </MessageScrollerViewport>
              <MessageScrollerButton />
            </MessageScroller>
          </MessageScrollerProvider>
        </CardContent>
        <CardFooter>
          <PromptInput
            onSubmit={onSubmit}
            status={status}
            defaultValue={
              isBusy ? "" : nextMessage ? getMessageText(nextMessage) : ""
            }
          />
        </CardFooter>
      </Card>
    </Example>
  )
}
"use client"

import * as React from "react"
import { type FileUIPart } from "ai"
import { cn } from "cn"

import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
  AttachmentTrigger,
} from "@/registry/bases/radix/ui/attachment"
import { Badge } from "@/registry/bases/radix/ui/badge"
import { IconPlaceholder } from "@/app/(app)/create/components/icon-placeholder"

function getFilename(part: FileUIPart) {
  if (part.filename) {
    return part.filename
  }

  try {
    const pathname = new URL(part.url).pathname
    const filename = pathname.split("/").filter(Boolean).pop()

    if (filename?.includes(".")) {
      return decodeURIComponent(filename)
    }
  } catch {
    const filename = part.url.split("?")[0]?.split("/").pop()

    if (filename?.includes(".")) {
      return filename
    }
  }

  return part.mediaType.startsWith("image/") ? "Image file" : "File"
}

export function PartFile({
  part,
  className,
}: { part: FileUIPart } & Omit<React.ComponentProps<"div">, "part">) {
  if (part.type !== "file") {
    return null
  }

  const isImage = part.mediaType.startsWith("image/")
  const filename = getFilename(part)

  if (isImage) {
    return (
      <Attachment
        orientation="vertical"
        className={cn("group/file w-full max-w-72", className)}
      >
        <AttachmentMedia variant="image" className="aspect-[4/3] w-full">
          <img src={part.url} alt={filename} />
        </AttachmentMedia>
        <AttachmentContent className="flex items-center gap-2">
          <AttachmentMedia className="size-7">
            <IconPlaceholder
              lucide="ImageIcon"
              tabler="IconPhoto"
              hugeicons="ImageIcon"
              phosphor="ImageIcon"
              remixicon="RiImageLine"
            />
          </AttachmentMedia>
          <span className="min-w-0 flex-1">
            <AttachmentTitle>{filename}</AttachmentTitle>
          </span>
          <Badge variant="outline" className="shrink-0">
            {part.mediaType.replace("image/", "").toUpperCase()}
          </Badge>
        </AttachmentContent>
        <AttachmentTrigger asChild>
          <a
            href={part.url}
            target="_blank"
            rel="noreferrer"
            aria-label={`Open ${filename}`}
          />
        </AttachmentTrigger>
      </Attachment>
    )
  }

  return (
    <Attachment className={cn("w-full max-w-80", className)}>
      <AttachmentMedia>
        <IconPlaceholder
          lucide="FileTextIcon"
          tabler="IconFileText"
          hugeicons="FileIcon"
          phosphor="FileTextIcon"
          remixicon="RiFileTextLine"
        />
      </AttachmentMedia>
      <AttachmentContent>
        <AttachmentTitle>{filename}</AttachmentTitle>
        <AttachmentDescription>{part.mediaType}</AttachmentDescription>
      </AttachmentContent>
      <AttachmentActions>
        <AttachmentAction asChild aria-hidden="true">
          <span>
            <IconPlaceholder
              lucide="ExternalLinkIcon"
              tabler="IconExternalLink"
              hugeicons="LinkSquare02Icon"
              phosphor="ArrowSquareOutIcon"
              remixicon="RiExternalLinkLine"
            />
          </span>
        </AttachmentAction>
      </AttachmentActions>
      <AttachmentTrigger asChild>
        <a
          href={part.url}
          target="_blank"
          rel="noreferrer"
          aria-label={`Open ${filename}`}
        />
      </AttachmentTrigger>
    </Attachment>
  )
}
"use client"

import * as React from "react"
import { useChat } from "@ai-sdk/react"
import type { UIMessage } from "ai"

import { createChat, getMessageText } from "@/lib/ai"
import { PartText } from "@/registry/bases/radix/blocks/preview-03/components/part-text"
import { PromptInput } from "@/registry/bases/radix/blocks/preview-03/components/prompt-input"
import { Example } from "@/registry/bases/radix/components/example"
import { Button } from "@/registry/bases/radix/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/registry/bases/radix/ui/card"
import {
  Marker,
  MarkerContent,
  MarkerIcon,
} from "@/registry/bases/radix/ui/marker"
import {
  Message,
  MessageContent,
  MessageHeader,
} from "@/registry/bases/radix/ui/message"
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/registry/bases/radix/ui/message-scroller"
import { Spinner } from "@/registry/bases/radix/ui/spinner"
import { IconPlaceholder } from "@/app/(app)/create/components/icon-placeholder"

type Metadata = {
  name?: string
}

type ChatEventUserLeft = {
  type: "user-left"
  name: string
}

type ChatEventUserJoined = {
  type: "user-joined"
  name: string
}

type ChatEventUserTyping = {
  type: "user-typing"
  name: string
}

type ChatEvent = ChatEventUserLeft | ChatEventUserJoined | ChatEventUserTyping

type ScriptedChatEvent = ChatEvent & {
  order: number
  delayMs: number
}

type ChatMessage = UIMessage<Metadata>

const scriptedEvents = [
  { type: "user-joined", name: "Stella", order: 0.5, delayMs: 2000 },
  { type: "user-typing", name: "Stella", order: 0.5, delayMs: 4000 },
  { type: "user-joined", name: "Marcus", order: 1.5, delayMs: 2000 },
  { type: "user-typing", name: "Marcus", order: 1.5, delayMs: 4000 },
  { type: "user-joined", name: "Aleena", order: 2.5, delayMs: 0 },
  { type: "user-typing", name: "Aleena", order: 3.5, delayMs: 0 },
  { type: "user-left", name: "Aleena", order: 5.5, delayMs: 2000 },
] satisfies ScriptedChatEvent[]

const chat = createChat<ChatMessage>()
  .user(
    "Hey everyone — dinner this Saturday? I was thinking something casual at my place."
  )
  .user(
    "I'm in! Should we do potluck or does someone want to cook the whole thing?",
    {
      metadata: {
        name: "Stella",
      },
    }
  )
  .user("Potluck sounds good. I can handle appetizers and drinks.", {
    metadata: {
      name: "Marcus",
    },
  })
  .user("Alright! Aleena?")
  .user("Can't make it. I'm out of town. 😭", {
    metadata: {
      name: "Aleena",
    },
  })
  .user("Sorry guys, let's catch up another time. Bye.", {
    metadata: {
      name: "Aleena",
    },
  })
  .user(
    "@chat, can you suggest a menu and split up what each of us should bring?"
  )
  .sleep(1000)
  .assistant(
    `Here's a simple **Saturday potluck** for the three of you:

**Who brings what**
- **You:** main — salmon or mushroom risotto
- **Stella:** salad + bread
- **Marcus:** appetizers + drinks
- **Chat:** dessert ideas below

**Menu**
- **Starter:** caprese skewers or whipped ricotta crostini
- **Main:** lemon-herb salmon with roasted asparagus *(or risotto for vegetarians)*
- **Side:** arugula salad with shaved parmesan
- **Dessert:** berry crisp or pistachio gelato

**Timing:** aim for **6:30 PM** so Marcus can set up apps while you finish the main.

Want me to scale this for **6 guests** or swap the main for something vegetarian-only?`
  )

const INITIAL_MESSAGE_COUNT = 0

const initialMessages = chat.get(INITIAL_MESSAGE_COUNT)
const transport = chat.transport()

export function GroupChat() {
  const eventRunRef = React.useRef(0)
  const [events, setEvents] = React.useState<ScriptedChatEvent[]>(() =>
    scriptedEvents.filter((event) => event.order < INITIAL_MESSAGE_COUNT)
  )
  const { status, messages, sendMessage, setMessages } = useChat<ChatMessage>({
    messages: initialMessages,
    transport,
  })
  const nextMessage = chat.next(messages)
  const isBusy = status === "submitted" || status === "streaming"
  const senderName = nextMessage?.metadata?.name ?? "You"

  const onSubmit = (input: string) => {
    if (!input.trim()) {
      return
    }

    if (nextMessage && input === getMessageText(nextMessage)) {
      const message = nextMessage
      const messageIndex = messages.length
      const eventRun = eventRunRef.current + 1
      const nextEvents = scriptedEvents
        .filter((event) => event.order > messageIndex)
        .filter((event) => event.order < messageIndex + 1)
        .filter(
          (event) =>
            !(
              event.type === "user-typing" &&
              event.name === message.metadata?.name
            )
        )

      eventRunRef.current = eventRun
      setEvents((events) =>
        events.filter(
          (event) =>
            !(
              event.type === "user-typing" &&
              event.name === message.metadata?.name
            )
        )
      )

      if (getMessageText(message).trim().toLowerCase().startsWith("@chat,")) {
        void sendMessage(nextMessage)
        return
      }

      setMessages((messages) => [...messages, message])

      void (async () => {
        let previousDelayMs = 0

        for (const event of nextEvents) {
          const delayMs = Math.max(0, event.delayMs - previousDelayMs)
          previousDelayMs = event.delayMs

          if (delayMs > 0) {
            await new Promise((resolve) => setTimeout(resolve, delayMs))
          }

          if (eventRunRef.current !== eventRun) {
            return
          }

          setEvents((events) =>
            [
              ...events.filter(
                (currentEvent) =>
                  !(
                    currentEvent.type === event.type &&
                    currentEvent.name === event.name
                  )
              ),
              event,
            ].sort((a, b) => a.order - b.order)
          )
        }
      })()
      return
    }

    void sendMessage({
      text: input,
    })
  }

  return (
    <Example
      title="Group Chat"
      className="bg-transparent p-0"
      containerClassName="flex-1"
    >
      <Card className="max-h-140 min-h-0 flex-1">
        <CardHeader>
          <CardTitle>Saturday dinner plans</CardTitle>
          <CardDescription className="leading-relaxed">
            A group chat with multiple users. Includes tinted bubbles for user
            messages.
          </CardDescription>
          <CardAction>
            <Button
              variant="outline"
              size="icon"
              aria-label="Start over"
              onClick={() => {
                eventRunRef.current += 1
                setMessages(initialMessages)
                setEvents(
                  scriptedEvents.filter(
                    (event) => event.order < INITIAL_MESSAGE_COUNT
                  )
                )
              }}
            >
              <IconPlaceholder
                lucide="PlusIcon"
                tabler="IconPlus"
                hugeicons="PlusSignIcon"
                phosphor="PlusIcon"
                remixicon="RiAddLine"
              />
            </Button>
          </CardAction>
        </CardHeader>
        <CardContent className="flex-1 overflow-hidden p-0">
          <MessageScrollerProvider>
            <MessageScroller>
              <MessageScrollerViewport>
                <MessageScrollerContent className="p-(--card-spacing)">
                  {messages.map((message, index) => {
                    const isOwnMessage =
                      message.role === "user" &&
                      message.metadata?.name === undefined
                    const startsModelTurn = getMessageText(message)
                      .trim()
                      .toLowerCase()
                      .startsWith("@chat,")

                    return (
                      <React.Fragment key={message.id}>
                        <MessageScrollerItem
                          messageId={message.id}
                          scrollAnchor={startsModelTurn}
                        >
                          <Message
                            align={isOwnMessage ? "end" : "start"}
                            data-role={message.role}
                          >
                            {!isOwnMessage && (
                              <MessageHeader>
                                {message.role === "assistant"
                                  ? "Chat"
                                  : message.metadata?.name || "Unknown"}
                              </MessageHeader>
                            )}
                            <MessageContent>
                              {message.parts.map((part, index) => (
                                <React.Fragment key={`${message.id}-${index}`}>
                                  {part.type === "text" ? (
                                    <PartText
                                      part={part}
                                      variant={
                                        message.role === "user"
                                          ? "bubble"
                                          : "default"
                                      }
                                      tinted={isOwnMessage}
                                    />
                                  ) : null}
                                </React.Fragment>
                              ))}
                            </MessageContent>
                          </Message>
                        </MessageScrollerItem>
                        {events
                          .filter((event) => event.order > index)
                          .filter((event) => event.order < index + 1)
                          .map((event) => (
                            <MessageScrollerItem
                              key={`${event.type}-${event.name}-${event.order}`}
                              scrollAnchor={false}
                            >
                              <Marker
                                variant={
                                  event.type === "user-typing"
                                    ? "default"
                                    : "separator"
                                }
                                role={
                                  event.type === "user-typing"
                                    ? "status"
                                    : undefined
                                }
                              >
                                <MarkerContent>
                                  {event.type === "user-joined"
                                    ? `${event.name} joined the chat`
                                    : event.type === "user-left"
                                      ? `${event.name} left the chat`
                                      : `${event.name} is typing...`}
                                </MarkerContent>
                              </Marker>
                            </MessageScrollerItem>
                          ))}
                      </React.Fragment>
                    )
                  })}
                  {status === "submitted" ? (
                    <MessageScrollerItem scrollAnchor={false}>
                      <Marker role="status">
                        <MarkerIcon>
                          <Spinner />
                        </MarkerIcon>
                        <MarkerContent>Thinking...</MarkerContent>
                      </Marker>
                    </MessageScrollerItem>
                  ) : null}
                </MessageScrollerContent>
              </MessageScrollerViewport>
              <MessageScrollerButton />
            </MessageScroller>
          </MessageScrollerProvider>
        </CardContent>
        <CardFooter className="flex-col items-stretch gap-2">
          <p className="px-1 text-xs text-muted-foreground">
            Posting as {senderName}.
          </p>
          <PromptInput
            onSubmit={onSubmit}
            status={status}
            defaultValue={
              isBusy ? "" : nextMessage ? getMessageText(nextMessage) : ""
            }
          />
        </CardFooter>
      </Card>
    </Example>
  )
}
"use client"

import * as React from "react"
import { useChat } from "@ai-sdk/react"

import { createChat, getMessageText } from "@/lib/ai"
import {
  getReasoningLevelLabel,
  PartReasoning,
} from "@/registry/bases/radix/blocks/preview-03/components/part-reasoning"
import { PartText } from "@/registry/bases/radix/blocks/preview-03/components/part-text"
import { PromptInput } from "@/registry/bases/radix/blocks/preview-03/components/prompt-input"
import { Example } from "@/registry/bases/radix/components/example"
import { Button } from "@/registry/bases/radix/ui/button"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/registry/bases/radix/ui/card"
import {
  Marker,
  MarkerContent,
  MarkerIcon,
} from "@/registry/bases/radix/ui/marker"
import { Message, MessageContent } from "@/registry/bases/radix/ui/message"
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/registry/bases/radix/ui/message-scroller"
import { Spinner } from "@/registry/bases/radix/ui/spinner"
import { IconPlaceholder } from "@/app/(app)/create/components/icon-placeholder"

const chat = createChat()
  .user("Explain why the dashboard feels slow even though the API is fast.")
  .sleep(1000)
  .assistant(({ writer }) => {
    writer.reasoning(
      `The user is separating perceived performance from backend latency. They likely measured API response times and found them acceptable, but users still complain about slowness.

I should avoid jumping straight to server-side optimizations and instead frame the answer around what people actually experience.`
    )
    writer.sleep(600)
    writer.reasoning(
      `Perceived slowness usually lives in the gap between user action and visible feedback:

- input latency before the request fires
- loading state placement and timing
- layout shifts when data arrives
- whether optimistic UI gives immediate acknowledgment

For a dashboard, I should also consider chart re-renders, independent card fetches, and skeleton dimensions that do not match the final layout.`
    )
    writer.sleep(600)
    writer.reasoning(
      `Ranking likely bottlenecks for this scenario:

1. No immediate feedback on filter or refresh actions
2. Skeleton cards that collapse or expand when data lands
3. Waterfall requests where each widget fetches on its own
4. Empty-state flashes because stale data is not shown while revalidating

The answer should stay practical and ordered by impact, not by how technical each fix sounds.`
    )
    writer.text(
      `The API can be fast while the interface still **feels** slow.

Start by checking:

- whether the button gives immediate feedback
- whether skeletons match the final layout
- whether any reflow happens after data arrives
- whether the loading state appears near the content it replaces`
    )
  })
  .user("What should I fix first?")
  .sleep(1000)
  .assistant(({ writer }) => {
    writer.reasoning(
      `The user wants prioritization, not another diagnostic list.

Given the dashboard context, immediate feedback and layout stability usually beat micro-optimizations. I should recommend one fix with a clear way to measure success.`
    )
    writer.text(
      `Fix **immediate feedback** first.

When someone clicks "Refresh", the button should disable and show a spinner within one frame — before the network round trip. That single change often cuts perceived latency in half.

Measure it with a screen recording and count frames between click and visual response.`
    )
  })

const initialMessages = chat.get(0)
const transport = chat.transport()

export function ReasoningChat() {
  const { status, messages, sendMessage, setMessages } = useChat({
    messages: initialMessages,
    transport,
  })
  const nextMessage = chat.next(messages)
  const isBusy = status === "submitted" || status === "streaming"

  const onSubmit = (input: string) => {
    if (!input.trim()) {
      return
    }

    if (nextMessage && input === getMessageText(nextMessage)) {
      void sendMessage(nextMessage)
      return
    }

    void sendMessage({ text: input })
  }

  return (
    <Example
      title="Reasoning"
      className="bg-transparent p-0"
      containerClassName="flex-1"
    >
      <Card className="max-h-140 min-h-0 flex-1">
        <CardHeader>
          <CardTitle>Reasoning trace</CardTitle>
          <CardDescription>
            Layered reasoning traces across multiple assistant turns.
          </CardDescription>
          <CardAction>
            <Button
              variant="outline"
              size="icon"
              aria-label="Start over"
              onClick={() => setMessages(initialMessages)}
            >
              <IconPlaceholder
                lucide="PlusIcon"
                tabler="IconPlus"
                hugeicons="PlusSignIcon"
                phosphor="PlusIcon"
                remixicon="RiAddLine"
              />
            </Button>
          </CardAction>
        </CardHeader>
        <CardContent className="flex-1 overflow-hidden p-0">
          <MessageScrollerProvider>
            <MessageScroller>
              <MessageScrollerViewport>
                <MessageScrollerContent className="p-(--card-spacing)">
                  {messages.map((message) => (
                    <MessageScrollerItem
                      key={message.id}
                      messageId={message.id}
                      scrollAnchor={message.role === "user"}
                    >
